package org.slavicmyths.nethersmithing;
import java.util.*;import net.minecraft.nbt.*;import net.minecraft.core.component.DataComponents;import net.minecraft.world.item.*;import net.minecraft.world.item.component.CustomData;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.entity.*;import net.minecraft.world.phys.*;import net.minecraft.world.level.ClipContext;import net.minecraft.world.effect.*;
/** Bounded skills through existing player damage/weapon/projectile pipelines. */
public final class NetherSkills {
 public static long now(ServerPlayer p){return p.getServer().overworld().getGameTime();}
 private static CompoundTag data(ServerPlayer p){var root=org.slavicmyths.rpg.PathData.data(p);if(!root.contains("NetherSkills",10))root.put("NetherSkills",new CompoundTag());return root.getCompound("NetherSkills");}
 public static long readyAt(ServerPlayer p,ItemStack s,String id){return Math.max(data(p).getLong(id),s.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag().getLong("slavicmyths_skill_"+id));}
 public static boolean ready(ServerPlayer p,ItemStack s,String id){return p.isAlive()&&!p.isSpectator()&&now(p)>=readyAt(p,s,id);}
 public static void stackReady(ItemStack s,String id,long at){CustomData.update(DataComponents.CUSTOM_DATA,s,t->t.putLong("slavicmyths_skill_"+id,at));}
 public static void consume(ServerPlayer p,ItemStack s,String id){long until=now(p)+NetherWeaponRules.cooldown(id);data(p).putLong(id,until);stackReady(s,id,until);p.displayClientMessage(net.minecraft.network.chat.Component.translatable("netherweapons.skill_used",s.getHoverName(),NetherWeaponRules.cooldown(id)/20),true);}
 public static void waitMessage(ServerPlayer p,ItemStack s,String id){p.displayClientMessage(net.minecraft.network.chat.Component.translatable("netherweapons.cooldown",Math.max(0,(readyAt(p,s,id)-now(p)+19)/20)),true);}
 public static boolean legal(ServerPlayer p,LivingEntity target){return target!=p&&target.isAlive()&&!target.isSpectator()&&org.slavicmyths.rpg.Abilities.canHit(p,target)&&!p.isAlliedTo(target)&&p.hasLineOfSight(target);}
 public static boolean hit(ServerPlayer p,ItemStack stack,LivingEntity target,float raw,float kb){if(!legal(p,target))return false;var source=p.damageSources().playerAttack(p);float damage=net.minecraft.world.item.enchantment.EnchantmentHelper.modifyDamage(p.serverLevel(),stack,target,source,raw);if(!target.hurt(source,damage))return false;net.minecraft.world.item.enchantment.EnchantmentHelper.doPostAttackEffectsWithItemSource(p.serverLevel(),target,source,stack);if(kb>0){var d=target.position().subtract(p.position());target.knockback(kb,-d.x,-d.z);}p.setLastHurtMob(target);return true;}
 public static void release(ServerPlayer p,ItemStack stack,String id,int held){if(held<NetherWeaponRules.charge(id)||!p.getMainHandItem().equals(stack)||!ready(p,stack,id)||id.equals("ashen_greatsword")&&!p.getOffhandItem().isEmpty())return;consume(p,stack,id);
  if(id.equals("navya_ostroga")){Vec3 eye=p.getEyePosition(),end=eye.add(p.getLookAngle().scale(4.25));var wall=p.serverLevel().clip(new ClipContext(eye,end,ClipContext.Block.COLLIDER,ClipContext.Fluid.NONE,p));if(wall.getType()!=HitResult.Type.MISS)end=wall.getLocation();var finalEnd=end;LivingEntity chosen=null;double best=eye.distanceToSqr(end);for(var t:p.serverLevel().getEntitiesOfClass(LivingEntity.class,new AABB(eye,end).inflate(.35),t->legal(p,t))){var point=t.getBoundingBox().inflate(.15).clip(eye,finalEnd);if(point.isPresent()&&eye.distanceToSqr(point.get())<=best){best=eye.distanceToSqr(point.get());chosen=t;}}if(chosen!=null&&hit(p,stack,chosen,13,0))chosen.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SLOWDOWN,40,1),p);
  }else{boolean flail=id.equals("volcanic_heart_flail");double radius=flail?3.25:3.5;var targets=p.serverLevel().getEntitiesOfClass(LivingEntity.class,p.getBoundingBox().inflate(radius),t->legal(p,t)&&t.distanceToSqr(p)<=radius*radius&&(flail||t.position().subtract(p.position()).multiply(1,0,1).normalize().dot(p.getLookAngle().multiply(1,0,1).normalize())>=Math.cos(Math.toRadians(50))));targets.sort(Comparator.comparingDouble(t->t.distanceToSqr(p)));for(var target:targets.stream().limit(flail?4:3).toList())if(hit(p,stack,target,flail?8:18,flail?1.2F:.6F)&&flail&&!target.fireImmune()&&!target.hasEffect(MobEffects.FIRE_RESISTANCE)){target.setRemainingFireTicks(Math.max(target.getRemainingFireTicks(),160));org.slavicmyths.burningislands.TemporaryTerrain.fire(p,target);}}
  stack.hurtAndBreak(id.equals("ashen_greatsword")?5:4,p,EquipmentSlot.MAINHAND);p.swing(net.minecraft.world.InteractionHand.MAIN_HAND,true);
 }
 public static void knifeHit(ServerPlayer p,LivingEntity target,boolean skill){long now=now(p);var tag=target.getPersistentData();if(!skill&&tag.getLong("NetherKnifeProc")>now)return;if(skill||p.getRandom().nextFloat()<.2F){target.addEffect(new MobEffectInstance(MobEffects.WEAKNESS,skill?60:40,0),p);tag.putLong("NetherKnifeProc",now+80);if(skill){tag.putLong("NetherKnifeArmorUntil",now+60);NetherWeaponEffects.armorDebuff(target,true);}}}
 private NetherSkills(){}
}
